-- AgriGuide Connect / Kisan Sahayak: Supabase (Postgres) schema
-- Run this whole file once in Supabase: SQL Editor -> New query -> paste -> Run.
--
-- 1) query_log: one row per farmer question, plus thumbs-up/down feedback.
--    NOTE: it stores Telegram chat IDs and messages (personal data).
--    Never commit exported rows from this table to a public repository.

create table if not exists query_log (
  id bigint generated always as identity primary key,
  created_at timestamptz default now(),
  chat_id bigint,
  message text,
  reply text,
  escalated boolean,
  feedback text
);

-- 2) crop_knowledge and state_crops: the knowledge base the agent looks up.

-- Crop Advisor Agent: knowledge database for Supabase (Postgres)
-- Run this whole file once in Supabase: SQL Editor -> New query -> paste -> Run.
-- It REPLACES any earlier crop_knowledge table and creates state_crops.
--
-- IMPORTANT: this is general agronomy guidance compiled for a student prototype.
-- Values are approximate. Verify key figures (sowing windows, temperatures, soil pH,
-- problems) with ICAR, your state agricultural university and the local KVK before
-- relying on them.

drop table if exists crop_knowledge;
drop table if exists state_crops;

create table crop_knowledge (
  id bigint generated always as identity primary key,
  crop text not null,
  hindi_name text,
  category text,
  season text,
  sowing_window text,
  duration_days text,
  optimum_temp_c text,
  water_requirement text,
  soil_type text,
  soil_ph text,
  major_states text,
  common_problems text,
  weather_sensitivity text,
  nutrient_notes text,
  basic_advice text
);

create table state_crops (
  id bigint generated always as identity primary key,
  state text not null,
  region text,
  climate text,
  rainfall_mm text,
  temperature_c text,
  dominant_soils text,
  kharif_crops text,
  rabi_crops text,
  zaid_crops text,
  key_risks text
);

